export const code = async (inputs) => {
  const ctEq = (a, b) => {
    const x = String(a === undefined || a === null ? '' : a);
    const y = String(b === undefined || b === null ? '' : b);
    let diff = x.length ^ y.length;
    const n = x.length > y.length ? x.length : y.length;
    for (let i = 0; i < n; i++) {
      const cx = i < x.length ? x.charCodeAt(i) : 0;
      const cy = i < y.length ? y.charCodeAt(i) : 0;
      diff |= cx ^ cy;
    }
    return diff === 0;
  };

  const provided = String(inputs.providedSig === undefined || inputs.providedSig === null ? '' : inputs.providedSig);
  const expected = String(inputs.expectedSig === undefined || inputs.expectedSig === null ? '' : inputs.expectedSig);
  const valid = provided.length === 10 && expected.length === 10 && ctEq(provided, expected);

  return { valid: valid };
};

export const code = async (inputs) => {
  const crypto = require('node:crypto');

  const eventId = String(inputs.signEventId === undefined || inputs.signEventId === null ? '' : inputs.signEventId);
  const userId = String(inputs.signUserId === undefined || inputs.signUserId === null ? '' : inputs.signUserId);
  const qrSigningKey = String(inputs.qrSigningKey === undefined || inputs.qrSigningKey === null ? '' : inputs.qrSigningKey);

  const msg = 'c:' + eventId + ':' + userId;
  const raw = crypto.createHmac('sha256', qrSigningKey).update(msg, 'utf8').digest('base64');
  const b64url = raw.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
  const sig = b64url.slice(0, 10);
  if (sig.length !== 10) throw new Error('fn-verify-qr: short hmac output');

  return { sig: sig };
};
